"""Run every named query in sql/hr_analysis.sql against the SQLite DB and write a Markdown results report."""
import re
import sqlite3
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sql = (ROOT / "sql" / "hr_analysis.sql").read_text(encoding="utf-8")
blocks = re.split(r"^-- name: (\w+)\s*$", sql, flags=re.M)[1:]
con = sqlite3.connect(ROOT / "data" / "workforce_pulse.db")

out = ["# SQL Results — Phase 3", "",
       "Generated by `python tools/run_sql.py` from `sql/hr_analysis.sql` (SQLite engine).", ""]
for name, body in zip(blocks[::2], blocks[1::2]):
    comments = [l[2:].strip() for l in body.strip().splitlines() if l.startswith("--")]
    query = "\n".join(l for l in body.strip().splitlines() if not l.startswith("--"))
    df = pd.read_sql_query(query, con)
    out += [f"## {name}", *([f"*{' '.join(comments)}*", ""] if comments else []), df.to_markdown(index=False), ""]
    print(f"{name}: {len(df)} rows")
(ROOT / "reports" / "sql_results.md").write_text("\n".join(out), encoding="utf-8")
print("wrote reports/sql_results.md")
